package security;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.*;
@WebFilter("/*") public class SecurityFilter implements Filter {public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest q=(HttpServletRequest)req;HttpServletResponse p=(HttpServletResponse)res;p.setHeader("X-Content-Type-Options","nosniff");p.setHeader("X-Frame-Options","DENY");p.setHeader("Referrer-Policy","same-origin");p.setHeader("Permissions-Policy","camera=(self)");if(java.util.Set.of("POST","PUT","PATCH","DELETE").contains(q.getMethod().toUpperCase(java.util.Locale.ROOT))){HttpSession s=q.getSession(false);String expected=s==null?null:(String)s.getAttribute("csrfToken"),actual=q.getParameter("csrfToken");if(actual==null)actual=q.getHeader("X-CSRF-Token");if(expected==null||actual==null||!java.security.MessageDigest.isEqual(expected.getBytes(java.nio.charset.StandardCharsets.UTF_8),actual.getBytes(java.nio.charset.StandardCharsets.UTF_8))){p.sendError(403,"Request could not be verified");return;}}chain.doFilter(req,res);}}